import{_ as l,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-11-04","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-11-04","date":"2021-11-04T00:00:00.000Z","updated":"2021-11-05T00:00:00.000Z","tags":["Ceph","分布式存储","性能测试","CI/CD","蓝鲸存储","FIO测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-11-04.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-11-04.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Performance_Meeting_2021-11-04.md"};function r(n,i,s,c,h,d){return e(),a("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了Ceph项目的最新进展，包括新提交的PR（Pull Request）、已关闭的PR以及性能测试相关的话题。会议重点关注了BlueStore的细粒度锁定、请求超时问题优化、性能测试CI的现状和改进建议等议题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新PR讨论</strong></p><ul><li><strong>Adam的BlueStore fine grain locking PR</strong>：这是一个重新尝试引入的PR，讨论了其复杂性和潜在的性能提升。</li><li><strong>优化请求超时问题</strong>：Casey提交了一个新的PR，通过引入自定义分配器等方法优化了请求超时问题，显著提升了性能，并讨论了CPU使用率的变化和后续的测试计划。</li></ul></li><li><p><strong>性能测试CI工作</strong></p><ul><li>讨论了当前性能测试CI的现状和存在的问题，特别是关于Classic PRs的性能测试未自动运行的问题。</li><li>提出了扩展测试工作负载的建议，包括引入FIO测试，并讨论了如何改进和扩展现有的性能测试框架。</li><li>讨论了多节点测试的必要性和可行性，以及如何处理非默认配置（如禁用数据CRC）的问题。</li></ul></li><li><p><strong>其他更新和讨论</strong></p><ul><li>讨论了其他几个PR的更新情况，包括优化内存使用、配置调整等。</li><li>提到了一些长期未有进展的PR，强调了继续讨论和评估的重要性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了需要进一步调查为何带有性能标签的Classic PRs未自动运行性能测试。</li><li>决定扩展性能测试框架，首先引入FIO测试，并考虑多节点测试的可行性。</li><li>讨论了性能测试中非默认配置的问题，建议根据PR的具体内容决定是否启用某些配置。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>调查并解决Classic PRs性能测试未自动运行的问题。</li><li>扩展性能测试框架，引入FIO测试，并考虑多节点测试。</li><li>继续讨论和评估长期未有进展的PR，确保项目的持续改进和发展。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>确认了下一次会议将讨论Crimson相关的内容，再下一次会议将讨论Balancer的包装器。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献，并期待下一次会议的讨论。</p><p>[改进后的总结内容中包含的Ceph相关关键词]</p><ul><li>Ceph</li><li>distributed storage</li><li>CRUSH algorithm</li><li>high availability</li><li>scalability</li><li>object storage</li><li>block storage</li><li>file system storage</li><li>consistency</li><li>decentralization</li><li>performance</li><li>BlueStore</li><li>BlueFS</li><li>RocksDB</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>authentication</li><li>authorization</li><li>encryption</li><li>erasure coding</li><li>replication</li><li>snapshots</li><li>clones</li><li>thin provisioning</li><li>iSCSI</li><li>Fibre Channel</li><li>NFS</li><li>CIFS</li><li>POSIX</li><li>monitoring</li><li>dashboard</li><li>management</li><li>orchestration</li><li>automation</li><li>integration</li><li>containerization</li><li>Kubernetes</li><li>Docker</li><li>virtualization</li><li>cloud computing</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>hybrid cloud</li><li>multi-cloud</li><li>storage cluster</li><li>node</li><li>disk</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>network</li><li>topology</li><li>failure domain</li><li>recovery</li><li>resilience</li><li>load balancing</li><li>caching</li><li>compression</li><li>deduplication</li><li>tiering</li><li>performance tuning</li><li>benchmarking</li><li>testing</li><li>validation</li></ul>',15)])])}const g=l(o,[["render",r]]);export{p as __pageData,g as default};
